write('accepted-obligations-v1.json',dict(required=[dict(name=n,statement_hash=h,state='accepted-source-Jensen-endpoint-or-necessary-negative-part-producer') for n,h in freeze['headers'].items()],source_printed_results=1,new_proofs=0,new_definitions=0,remaining_chapter_legacy_migrations=13,legacy_migrations_before=14,exact_accepted_legacy_delta='OnlineJensen only; retained source endpoint semantically revalidated, no new mathematical proof-count gain',chapter_total=None,future_chapters='3-16 unenumerated mandatory',main_missing_changed_production_contract_paths=11,**boundary))
write('source-inventory-acceptance-overlay-v1.json',dict(base_inventory='docs/contracts/online-book-v1/source-inventory.json',base_sha256=sha('docs/contracts/online-book-v1/source-inventory.json'),additive_only=True,source_anchor='Theorem2.9 printed11/PDF23',accepted_public_names=['BanditRL.OnlineConvex.'+n for n in freeze['headers']],delta='One source Jensen result and its negative-part producer, two retained proofs, no added loss-integrability/closedness premise. Finite Lebesgue mean interpretation and finiteD Borel normed generality explicit.',**boundary))
